  .verdict.good{animation:verdict-pass .5s ease-out}

  /* the slim progression strip: one dot per lesson under the lesson nav */
  .progress-strip{display:flex;justify-content:center;gap:9px;margin:2px 0 12px}
  .progress-strip .dot{
    width:9px;height:9px;border-radius:50%;
    background:var(--deep);border:1px solid var(--line);
    transition:background .3s,border-color .3s,box-shadow .3s;
  }
  .progress-strip .dot.passed{
    background:var(--accent);border-color:var(--accent);
    box-shadow:0 0 6px rgba(127,212,193,.45);
  }

